import {playerName,canUseName} from './NamePolicy';
import type {Profile} from './PlayerStore';
import {MailReward,applyGift,canClaimMail} from './GiftPolicy';
import {getApps,getFirestore,doc,getDocFromServer,getDocs,collection,query,where,runTransaction,serverTimestamp} from '../vendor/firebase-sdk.js';
import {LocalStorage} from './AccountStorage';
import {validatePolicy} from './LivePolicy';
const db=()=>getFirestore(getApps().find(a=>a.name==='in-my-pocket')!);
export async function fetchLivePolicy(){const s=await getDocFromServer(doc(db(),'operations','live'));if(!s.exists())throw Error('운영 설정이 없습니다.');return validatePolicy(s.data());}
export async function fetchMailbox(uid:string){const [mail,claims]=await Promise.all([getDocs(query(collection(db(),'mailRewards'),where('audience','in',['all',uid]))),getDocs(collection(db(),'playerSaves',uid,'mailClaims'))]);const claimed=new Set(claims.docs.map(d=>d.id));return mail.docs.map(d=>({...d.data(),id:d.id}) as MailReward).filter(m=>m.status==='active'&&m.expiresAt>Date.now()).sort((a,b)=>b.createdAt-a.createdAt).map(m=>({...m,claimed:claimed.has(m.id)}));}
/** Server snapshot wins. Revision checks prevent two devices from overwriting each other. */
export class CloudSave implements LocalStorage {
 private value:string|null=null;private revision=0;private tail:Promise<void>=Promise.resolve();pending=0;error='';private claiming=false;private naming=false;
 private constructor(private uid:string,private changed:()=>void){}
 static async open(uid:string,changed:()=>void,legacy?:LocalStorage){const store=new CloudSave(uid,changed),s=await getDocFromServer(doc(db(),'playerSaves',uid));if(s.exists()){store.value=JSON.stringify(s.data().save);store.revision=s.data().revision;}else store.value=legacy?.getItem('midnight-slots-v1')||null;return store;}
 getItem(){return this.value;}
 setItem(_key:string,value:string){
  if(this.claiming||this.naming)throw Error('계정 정보를 처리하는 동안 저장할 수 없습니다.');if(this.error)throw Error(this.error);const save=JSON.parse(value);this.value=value;this.pending++;
  this.tail=this.tail.then(async()=>{if(this.error)return;const expected=this.revision;await runTransaction(db(),async tx=>{const ref=doc(db(),'playerSaves',this.uid),s=await tx.get(ref);if((s.exists()?s.data().revision:0)!==expected)throw Error('다른 기기에서 진행 상황이 변경되었습니다. 서버 저장을 다시 불러와 주세요.');tx.set(ref,{save,revision:expected+1,updatedAt:serverTimestamp()});});this.revision=expected+1;}).catch(error=>{this.error=error?.message?.includes('다른 기기')?error.message:'서버 저장을 확인하지 못했습니다. 연결 후 서버 저장을 다시 불러와 주세요.';}).finally(()=>{this.pending--;this.changed();});
  Promise.resolve().then(()=>this.changed());
 }
 async nameAvailable(value:string){const name=playerName(value),snapshot=await getDocFromServer(doc(db(),'playerNames',name.key));return canUseName(snapshot.exists()?snapshot.data().uid:undefined,this.uid);}
 async registerProfile(profile:Profile){
  if(this.claiming||this.naming)throw Error('계정 정보를 처리하고 있습니다.');const name=playerName(profile.name);this.naming=true;this.pending++;this.changed();
  try{await this.flush();const expected=this.revision;const result=await runTransaction(db(),async tx=>{
   const saveRef=doc(db(),'playerSaves',this.uid),nameRef=doc(db(),'playerNames',name.key);const [snapshot,claim]=await Promise.all([tx.get(saveRef),tx.get(nameRef)]);
   if(!snapshot.exists()||snapshot.data().revision!==expected)throw Error('서버 저장이 변경되었습니다. 다시 로그인해 주세요.');
   if(!canUseName(claim.exists()?claim.data().uid:undefined,this.uid))throw Error('이미 사용 중인 이름입니다.');
   const current=snapshot.data().save;if(current.pendingRound)throw Error('플레이가 끝난 뒤 이름을 정해 주세요.');
   if(current.profile&&current.profile.name!==name.display)throw Error('이미 이름을 정한 계정입니다.');
   const save={...current,profile:{...profile,name:name.display}},revision=expected+1;
   if(!claim.exists())tx.set(nameRef,{uid:this.uid,name:name.display,createdAt:serverTimestamp()});
   tx.set(saveRef,{save,revision,updatedAt:serverTimestamp()});return {save,revision};
  });this.value=JSON.stringify(result.save);this.revision=result.revision;
  }catch(error){
   // A commit acknowledgement can be lost. Only accept recovery if BOTH documents agree.
   try{const [claim,saved]=await Promise.all([getDocFromServer(doc(db(),'playerNames',name.key)),getDocFromServer(doc(db(),'playerSaves',this.uid))]);if(claim.exists()&&claim.data().uid===this.uid&&saved.exists()&&saved.data().save.profile?.name===name.display){this.value=JSON.stringify(saved.data().save);this.revision=saved.data().revision;return;}}catch{}
   throw error;
  }finally{this.naming=false;this.pending--;this.changed();}
 }
 async claimMail(id:string){
  if(this.claiming||this.naming)throw Error('계정 정보를 처리하고 있습니다.');this.claiming=true;this.pending++;this.changed();
  try{
   await this.flush();const expected=this.revision;
   const result=await runTransaction(db(),async tx=>{
    const saveRef=doc(db(),'playerSaves',this.uid),mailRef=doc(db(),'mailRewards',id),claimRef=doc(saveRef,'mailClaims',id);
    const [snapshot,mail,claim]=await Promise.all([tx.get(saveRef),tx.get(mailRef),tx.get(claimRef)]);
    if(!snapshot.exists())throw Error('서버 저장을 먼저 불러와 주세요.');
    const current=snapshot.data();if(claim.exists())return {save:current.save,revision:Number(current.revision),alreadyClaimed:true};
    if(current.revision!==expected)throw Error('다른 기기에서 진행 상황이 변경되었습니다.');
    if(!mail.exists()||!canClaimMail({...mail.data(),id} as MailReward,this.uid,Date.now()))throw Error('수령 대상이 아니거나 만료된 우편입니다.');
    if(current.save.pendingRound)throw Error('회차 정산 후 수령해 주세요.');
    const save=applyGift(current.save,mail.data().gift),revision=expected+1;
    tx.set(saveRef,{save,revision,updatedAt:serverTimestamp()});
    tx.set(claimRef,{claimedAt:serverTimestamp(),revision});return {save,revision,alreadyClaimed:false};
   });
   this.value=JSON.stringify(result.save);this.revision=result.revision;return result.alreadyClaimed;
  }catch(error){
   // A competing claim or a lost commit response may already have awarded this mail.
   try{const receipt=await getDocFromServer(doc(db(),'playerSaves',this.uid,'mailClaims',id));if(receipt.exists()){const snapshot=await getDocFromServer(doc(db(),'playerSaves',this.uid));if(snapshot.exists()){this.value=JSON.stringify(snapshot.data().save);this.revision=snapshot.data().revision;return true;}}}catch{}
   const message=(error as Error).message||'';this.error=['다른 기기','수령 대상','회차 정산','보유 가능한'].some(text=>message.includes(text))?message:'선물 수령 결과를 확인하지 못했습니다. 서버 저장을 다시 불러와 주세요.';throw error;}
  finally{this.claiming=false;this.pending--;this.changed();}
 }
 async flush(){await this.tail;if(this.error)throw Error(this.error);}
}
