export const starterSlots=['cherry','animal','sushi-party'];
export const slotUnlocks=[...slots].sort((a,b)=>Number(b.config.id==='cherry')-Number(a.config.id==='cherry')).map(slot=>{const id=slot.config.id;return{id,price:starterSlots.includes(id)?0:slot.unlockPriceTenths*UNLOCK_PRICE_MULTIPLIER};});
export type Skin='black'|'white'|'yellow';
export type Gender='male'|'female';
export interface Profile {name:string;skin:Skin;gender:Gender;appearance?:string;}
interface PendingRound {ranking?:RankingRound;coins:number;tickets:number;ticketRemainder:number;spins:number;hitStreak:number;missStreak:number;perkRemainders:Record<string,number>;awards:PerkAward[];}
interface Save {version:3;rankingQueue:RankingRound[];favorites:string[];ticketAccrualVersion:2;rewards:RewardState;cosmeticEquipment:Partial<Record<EquipmentSlot,string>>;pendingRound?:PendingRound;hitStreak:number;missStreak:number;perkRemainders:Record<string,number>;unlocked:string[];coins:number;tickets:number;ticketRemainder:number;owned:string[];equipped:string;spins:number;profile:Profile|null;equipment:Partial<Record<EquipmentSlot,string>>;}
const fresh=():Save=>({version:3,rankingQueue:[],favorites:[],ticketAccrualVersion:2,rewards:newRewards(),cosmeticEquipment:{},hitStreak:0,missStreak:0,perkRemainders:{},unlocked:[...starterSlots],coins:1000,tickets:0,ticketRemainder:0,owned:['night','basic-shorts','basic-hair'],equipped:'night',spins:0,profile:null,equipment:{top:'night',pants:'basic-shorts',hair:'basic-hair'}});
export class PlayerStore {
 data:Save=fresh();saveWarning=false;private staging=false;
 constructor(private storage:Pick<Storage,'getItem'|'setItem'>){
  try{const v=JSON.parse(storage.getItem('midnight-slots-v1')||'null');
   if(v&&(v.version===1||v.version===2||v.version===3)&&Number.isSafeInteger(v.coins)&&v.coins>=0&&Number.isSafeInteger(v.spins)&&v.spins>=0&&Array.isArray(v.owned)&&v.owned.includes('night')&&v.owned.every((id:unknown)=>costumes.some(c=>c.id===id))&&v.owned.includes(v.equipped)){
    this.data={...fresh(),rewards:normalizeRewards(v.rewards),coins:v.coins,spins:v.spins,owned:Array.from(new Set([...fresh().owned,...v.owned])),equipped:v.equipped};
    if(Array.isArray(v.rankingQueue))this.data.rankingQueue=v.rankingQueue.filter((r:RankingRound)=>r&&typeof r.id==='string'&&typeof r.slot==='string'&&typeof r.name==='string'&&Number.isSafeInteger(r.bet)&&Number.isSafeInteger(r.payout)&&Number.isSafeInteger(r.completedAt));
    if(Array.isArray(v.favorites))this.data.favorites=Array.from(new Set<string>(v.favorites.filter((id:unknown)=>slots.some(s=>s.config.id===id))));
    if(Array.isArray(v.unlocked)){for(const id of v.unlocked){if(id!=='cherry'&&slotUnlocks.some(rule=>rule.id===id)&&!this.data.unlocked.includes(id))this.data.unlocked.push(id);}}
    if(v.version>=2){if(Number.isSafeInteger(v.tickets)&&v.tickets>=0)this.data.tickets=v.tickets*(v.version===2?10:1);if(Number.isSafeInteger(v.ticketRemainder)&&v.ticketRemainder>=0&&v.ticketRemainder<(v.version===2?100:10)){this.data.ticketRemainder=v.ticketRemainder%10;if(v.version===2)this.data.tickets+=Math.floor(v.ticketRemainder/10);}
     if(v.version===3&&v.equipment){this.data.equipment={};for(const slot of equipmentSlots){const id=v.equipment[slot.id];if(this.data.owned.includes(id)&&costumes.some(c=>c.id===id&&c.slot===slot.id))this.data.equipment[slot.id]=id;else if(!['hair','top','pants'].includes(slot.id))delete this.data.equipment[slot.id];}}else{const old=costumes.find(c=>c.id===v.equipped);if(old)this.data.equipment[old.slot]=old.id;}
     if(v.profile&&typeof v.profile.name==='string'&&v.profile.name.trim().length>=1&&v.profile.name.length<=12&&['black','white','yellow'].includes(v.profile.skin)&&['male','female'].includes(v.profile.gender))this.data.profile={name:v.profile.name,skin:v.profile.skin,gender:v.profile.gender,...(avatarPreset(v.profile.appearance)?{appearance:v.profile.appearance}:{})};
    }
    if(v.cosmeticEquipment&&typeof v.cosmeticEquipment==='object')for(const slot of equipmentSlots){const id=v.cosmeticEquipment[slot.id];if(this.data.owned.includes(id)&&costumes.some(c=>c.id===id&&c.slot===slot.id))this.data.cosmeticEquipment[slot.id]=id;}
    for(const key of ['hitStreak','missStreak'] as const)if(Number.isSafeInteger(v[key])&&v[key]>=0)this.data[key]=v[key];
    if(v.perkRemainders&&typeof v.perkRemainders==='object')for(const id of Object.keys(v.perkRemainders)){const value=v.perkRemainders[id];if(costumes.some(c=>c.id===id)&&Number.isSafeInteger(value)&&value>=0&&value<1e12)this.data.perkRemainders[id]=value;}
    const pending=v.pendingRound;
    if(pending&&['coins','tickets','ticketRemainder','spins','hitStreak','missStreak'].every(k=>Number.isSafeInteger(pending[k])&&pending[k]>=0)&&pending.ticketRemainder<10&&pending.spins===this.data.spins+1&&Array.isArray(pending.awards)&&pending.perkRemainders&&Object.values(pending.perkRemainders).every(n=>Number.isSafeInteger(n)&&Number(n)>=0)){this.data.pendingRound=pending;this.finishRound();}
    if(v.ticketAccrualVersion!==2){for(const id of Object.keys(this.data.perkRemainders))if(costumePerks[id]?.currency==='tickets')this.data.perkRemainders[id]=Math.floor(this.data.perkRemainders[id]/(v.ticketAccrualVersion===1?100:10));this.data.ticketRemainder=0;this.save();}
    // Persist removal immediately so reopening cannot refund the same unlock twice.
    const retired=Array.isArray(v.unlocked)?['moon','garden'].filter(id=>v.unlocked.includes(id)):[];
    if(retired.length){this.data.tickets+=retired.length*300;this.save();}
   }
  }catch{this.saveWarning=true;}
 }
 save(){if(this.staging)return;try{this.storage.setItem('midnight-slots-v1',JSON.stringify(this.data));}catch{this.saveWarning=true;}}
 /** Reserve one wager and persist the outcome for crash/reload recovery. No rewards yet. */
 beginBonusRound(baseBet:number,payout:number,context?:Omit<PerkContext,'streak'|'misses'|'bet'|'payout'>){
  const before=JSON.parse(JSON.stringify(this.data)),cost=baseBet*20;if(!Number.isSafeInteger(cost)||this.data.coins<cost||this.data.tickets<150)throw Error('보너스 구매 잔액이 부족합니다.');
  try{this.data.tickets-=150;this.beginRound(cost,payout,context,undefined,false,baseBet,false);this.storage.setItem('midnight-slots-v1',JSON.stringify(this.data));}catch(error){this.data=before;throw error;}
 }
 beginRound(bet:number,payout:number,context?:Omit<PerkContext,'streak'|'misses'|'bet'|'payout'>,slot?:string,persist=true,tierBet=bet,awardTickets=true){
  if(this.data.pendingRound)throw Error('Round already active');
  const before=this.data;let pending:PendingRound;
  this.data=JSON.parse(JSON.stringify(before));this.staging=true;
  try{const awards=this.settle(bet,payout,context,tierBet,awardTickets);const {coins,tickets,ticketRemainder,spins,hitStreak,missStreak,perkRemainders}=this.data;pending={coins,tickets,ticketRemainder,spins,hitStreak,missStreak,perkRemainders,awards};}
  finally{this.data=before;this.staging=false;}
  if(slot)pending!.ranking={id:Date.now().toString(36)+'_'+Math.random().toString(36).slice(2)+'_'+Math.random().toString(36).slice(2),slot,bet,payout,completedAt:Date.now(),name:this.data.profile?.name||'게스트'};
  this.data.coins-=bet;this.data.pendingRound=pending!;if(persist)this.save();
 }
 /** Called once after every internal spin/cascade in the paid round has finished. */
 finishRound():PerkAward[]{const pending=this.data.pendingRound;if(!pending)return [];const {awards,ranking,...balances}=pending;Object.assign(this.data,balances);if(ranking&&!this.data.rankingQueue.some(r=>r.id===ranking.id))this.data.rankingQueue.push({...ranking,completedAt:Date.now()});delete this.data.pendingRound;this.save();return awards;}
 acknowledgeRanking(ids:string[]){const received=new Set(ids);this.data.rankingQueue=this.data.rankingQueue.filter(r=>!received.has(r.id));this.save();}
 setProfile(name:string,skin:Skin,gender:Gender,appearance?:string){name=name.trim();if(!name||name.length>12||!['black','white','yellow'].includes(skin)||!['male','female'].includes(gender))return false;if(appearance&&!avatarPreset(appearance))return false;this.data.profile={name,skin,gender,...(appearance?{appearance}:{})};this.save();return true;}
 reset(){
  const next=fresh();next.profile=this.data.profile?{...this.data.profile}:null;
  try{this.storage.setItem('midnight-slots-v1',JSON.stringify(next));this.data=next;this.staging=false;this.saveWarning=false;return true;}catch{this.saveWarning=true;return false;}
 }
 settle(bet:number,payout:number,context?:Omit<PerkContext,'streak'|'misses'|'bet'|'payout'>,tierBet=bet,awardTickets=true):PerkAward[]{if(!Number.isSafeInteger(bet)||bet<=0||!Number.isSafeInteger(payout)||payout<0||this.data.coins<bet||!Number.isSafeInteger(this.data.coins+payout-bet))throw Error('Invalid transaction');
  const streak=payout>0?this.data.hitStreak+1:0,bonus=context?resolvePerks(this.data.equipment,{...context,bet:tierBet,payout,streak,misses:this.data.missStreak},this.data.perkRemainders,awardTickets):{awards:[] as PerkAward[],remainders:this.data.perkRemainders,coins:0,tickets:0};
  const remainder=0,baseTickets=awardTickets?winTickets(payout,tierBet):0;
  if(!Number.isSafeInteger(this.data.coins+payout-bet+bonus.coins)||!Number.isSafeInteger(this.data.tickets+baseTickets+bonus.tickets))throw Error('Invalid bonus');this.data.coins+=payout-bet+bonus.coins;this.data.tickets+=baseTickets+bonus.tickets;this.data.ticketRemainder=remainder%10;this.data.perkRemainders=bonus.remainders;if(context){this.data.hitStreak=streak;this.data.missStreak=payout>0?0:this.data.missStreak+1;}this.data.spins++;this.save();return bonus.awards;
 }
 toggleFavorite(id:string){if(!slots.some(s=>s.config.id===id))return false;const favorites=this.data.favorites;this.data.favorites=favorites.includes(id)?favorites.filter(value=>value!==id):[...favorites,id];this.save();return this.data.favorites.includes(id);}
 buy(id:string):boolean{const c=costumes.find(c=>c.id===id);if(!c)return false;if(this.data.owned.includes(id))return false;if(this.data.tickets<c.price)return false;this.data.tickets-=c.price;this.data.owned.push(id);this.save();return true;}
 wear(id:string):boolean{const c=costumes.find(c=>c.id===id);if(!c||!this.data.owned.includes(id))return false;this.data.equipment[c.slot]=id;delete this.data.cosmeticEquipment[c.slot];this.data.equipped=id;this.save();return true;}
 get appearanceEquipment(){return {...this.data.equipment,...this.data.cosmeticEquipment};}
 wearAppearance(id:string):boolean{const c=costumes.find(c=>c.id===id);if(!c||!this.data.owned.includes(id))return false;this.data.cosmeticEquipment[c.slot]=id;if(this.data.equipment[c.slot]===id)delete this.data.equipment[c.slot];this.save();return true;}
 unlock(id:string){const index=slotUnlocks.findIndex(s=>s.id===id);if(index<0)return false;if(this.data.unlocked.includes(id))return true;const rule=slotUnlocks[index];if(this.data.tickets<rule.price)return false;this.data.tickets-=rule.price;this.data.unlocked.push(id);this.save();return true;}
 unequip(slot:EquipmentSlot){delete this.data.cosmeticEquipment[slot];if(['hair','top','pants'].includes(slot)){const defaults=fresh().equipment;this.data.equipment[slot]=defaults[slot];}else delete this.data.equipment[slot];this.save();}
 claimReward(currency:RewardCurrency,kind:'daily'|'ad',now=Date.now()){const amount=kind==='daily'?dailyRewardAmounts[currency]:rewardAmounts[currency];if(!Number.isSafeInteger(this.data[currency]+amount))return false;if(!consumeReward(this.data.rewards,currency,kind,now))return false;this.data[currency]+=amount;this.save();return true;}
 creditTestPurchase(coins:number){if(!Number.isSafeInteger(coins)||coins<=0||!Number.isSafeInteger(this.data.coins+coins))return false;this.data.coins+=coins;this.save();return true;}
 freeCoins(){if(!Number.isSafeInteger(this.data.coins+500))return false;this.data.coins+=500;this.save();return true;}
 refill():boolean{if(this.data.coins>=10)return false;this.data.coins+=300;this.save();return true;}
}
