import {native,sys} from 'cc';
export type AdOutcome='earned'|'closed'|'failed';
/** Google Mobile Ads native adapter. Web deliberately keeps the labelled simulation. */
export class RewardedAds {
 private pending=false;
 get supported(){return sys.isNative&&(sys.os===sys.OS.ANDROID||sys.os===sys.OS.IOS);}
 private invoke(method:'show'|'poll'|'cancel',id:string):string{
  if(sys.os===sys.OS.ANDROID)return native.reflection.callStaticMethod('com/cocos/game/PocketAds',method,'(Ljava/lang/String;)Ljava/lang/String;',id);
  return native.reflection.callStaticMethod('PocketAds',method+':',id);
 }
 async show():Promise<AdOutcome>{
  if(!this.supported||this.pending)return 'failed';this.pending=true;
  const id=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
  try{
   if(this.invoke('show',id)!=='loading')return 'failed';
   const started=Date.now();let showing=false;
   while(Date.now()-started<(showing?600000:60000)){
    await new Promise(resolve=>setTimeout(resolve,200));const state=this.invoke('poll',id);
    if(state==='earned'||state==='closed'||state==='failed')return state;
    if(state==='showing')showing=true;
   }
   return 'failed';
  }catch{return 'failed';}finally{try{this.invoke('cancel',id);}catch{}this.pending=false;}
 }
}
