import {SpinResult,SlotMain} from './SlotMain';
import {scalePayout} from './PayoutPolicy';
// Base-only paytable changes provide support for 10x+ regular wins; free-spin payouts retain their own scale.
export const basePayoutBoost:Record<string,number>={animal:4,'windup-workshop':10,'space-scrap':3,'mushroom-rush':2,'pizza-courier':8,'robot-duel':8,'coral-post':3,'neon-greenhouse':5};
export function boostBase(slot:SlotMain,result:SpinResult,rng:()=>number){const factor=basePayoutBoost[slot.config.id]||1;if(factor===1)return result;const base=result.rounds?.[0]||result;scalePayout(base,factor,rng);if(result.rounds)result.payout=result.rounds.reduce((n,r)=>n+r.payout,0);return result;}
