 setScene(scene:string,slot?:string){const next=scene==='shop'||scene==='wardrobe'?1:scene==='slot'?(slot==='cherry'?2:slot==='animal'?3:4):scene==='help'||scene==='cheat'?4:0;if(next!==this.base){this.base=next;this.loop=0;this.step=0;this.nextBeat=(this.ctx?.currentTime||0)+.12;}}
