 win(rank:number){if(rank<=this.winRank)return;this.winRank=rank;const c=this.ctx;if(!c||c.state!=='running'||this.muted||!this.fx)return;const now=c.currentTime,notes=[60,64,67,72,76,79,84,88].slice(0,4+rank);this.duckUntil=now+1.7;
  notes.forEach((note,i)=>this.tone(note+rank-1,now+i*.075,.34,.42,'triangle',this.fx!));[0,4,7,12].forEach(n=>{this.tone(72+n,now+.65,.7,.21,'sine',this.fx!);this.tone(60+n,now+.66,.8,.12,'triangle',this.fx!);});this.tone(36,now+.65,.32,.5,'sine',this.fx!,24);this.hiss(now+.63,.16,.12,1500);
 }
 get status(){return {enabled:!this.muted,state:this.ctx?.state||'locked',track:musicTracks[(this.base+this.loop)%5].name,tracks:musicTracks.length};}
